use core.files as files
use core.process as process
use core.text as text


struct Field {
    key: String
    value: String
}

struct Section {
    name: String
    fields: [Field]
    inherits: ?String
}

fn find_section(sections: [Section], name: String) ?Section -> {
    loop section in sections {
        if section.name == name -> return Val(section)
    }
    return None
}

fn resolved_fields(section: Section, sections: [Section]) [Field] -> {
    result := [Field]{}
    parent_name :: section.inherits ?? ""
    if !parent_name.is_empty() {
        parent :: find_section(sections, parent_name) ?? panic("missing inherited section {parent_name}")
        loop inherited in parent.fields {
            if inherited.key != "inherits" -> result.push(Field{key: inherited.key, value: inherited.value})
        }
    }
    loop field in section.fields {
        if field.key == "inherits" -> next
        replaced := false
        next_result := [Field]{}
        loop existing in result {
            if existing.key == field.key {
                next_result.push(Field{key: existing.key, value: field.value})
                replaced = true
            } else {
                next_result.push(existing)
            }
        }
        if !replaced -> next_result.push(Field{key: field.key, value: field.value})
        result = next_result
    }
    return result
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    source :: files.read(path) ?? panic("read failed")
    lines :: source.lines()
    sections := [Section]{}
    current := Section{name: "", fields: [Field]{}, inherits: None}
    have_section := false

    loop line in lines {
        trimmed :: ~(line.trim())
        if trimmed.is_empty() -> next
        if trimmed.contains("=") {
            if !have_section -> panic("field before section")
            parts :: text.splitn(trimmed, "=", 2)
            if parts.len() != 2 -> panic("malformed field")
            key :: parts.get(0) ?? panic("missing field key")
            raw_value :: parts.get(1) ?? panic("missing field value")
            raw_trimmed :: ~(raw_value.trim())
            value_parts :: text.splitn(raw_trimmed, "\"", 3)
            if value_parts.len() < 2 -> panic("field value must be quoted")
            value :: ~(value_parts.get(1) ?? panic("missing quoted value"))
            field_key :: ~(key.trim())
            loop existing in current.fields {
                if existing.key == field_key -> panic("duplicate field {field_key} in section {current.name}")
            }
            if field_key == "inherits" {
                current.inherits = Val(value)
            } else {
                current.fields.push(Field{key: field_key, value: value})
            }
        } else {
            header_parts :: text.splitn(trimmed, "[", 2)
            if header_parts.len() != 2 -> panic("malformed section header")
            header_body :: ~(header_parts.get(1) ?? panic("missing section name"))
            name_parts :: text.splitn(header_body, "]", 2)
            if name_parts.len() != 2 -> panic("malformed section header")
            name_raw :: name_parts.get(0) ?? panic("missing section name")
            section_name :: ~(name_raw.trim())
            if section_name.is_empty() -> panic("empty section name")
            if have_section -> sections.push(current)
            current = Section{name: section_name, fields: [Field]{}, inherits: None}
            have_section = true
        }
    }
    if have_section -> sections.push(current)

    output := ""
    loop section in sections {
        resolved :: resolved_fields(section, sections)
        loop field in resolved {
            output += "{section.name}.{field.key}={field.value}\n"
        }
    }
    print(output.trim())
}
